const std = @import("std");

// Compiled collection allowlist. CI rejects declared flags absent here.
pub const names = " accept-omissions ack-timeout-ms adapter after agents-registry all allow-attached-viewers allow-experimental allow-sensitive-capture allow-sensitive-storage allow-unavailable-target anchor answer app apply archive args arguments ask assertion autostart baseline basis before behaviour block board-store bounds brief-file by callback-config callback-host caller card card-file catalog channel-dir check checkpoint-every-bytes claim cleanup color columns command-json commit confidence config confirm context contradicts create-session cwd dashboard dashboard-block dashboard-host dashboard-session deactivate deadline-unix-ms definition deliver depends-on detach detail direction directory does-not-establish done draft draft-wait-ms end-of-options env-file establishes event-file event-id evidence evidence-check evidence-dir evidence-fd exclude-standard expect expect-generation exportable extension facts fields-file file fixture focus for-days format from from-owner gap-s generation gh handle harness help host hosts hypothesis-basis id include init intent interval-ms jobs-registry json keep-open kind label launch-id launch-wait-ms layout library limit list log-dir map-file max-bytes message-file metadata min-episodes name needs-review network no-deadline no-extensions no-optional-locks observation observations-out observe observe-max-bytes once operation option others out output-dir override-reason owner pace pane path payload plan policy porcelain print-config print-view process-exit profile profiles protect-file publish-receipt-file purpose ran ratio reason receipt-file recommend record-identities record-out ref registry relocate repo report-to-block report-to-session request-id resolve review-at rex root routed rows sample scene scope script seat server session settings since snapshot socket starter-block starter-session startup-ms state status-id status-message status-state stdin-file store tail target-check targets-file teerex term-json then timeout timeout-ms title to token tool ttl-seconds tty type value verify version view view-rules wait-ms wait-ms0 width window workdir write yes ";

pub fn allowed(name: []const u8) bool {
    var words = std.mem.tokenizeScalar(u8, names, ' ');
    while (words.next()) |word| if (std.mem.eql(u8, name, word)) return true;
    return false;
}
